'use client';

import { useEffect, useRef, useState } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';
import { FishManager, FishConfig } from '@/utils/FishManager';
import { supabase } from '@/lib/supabaseClient';
import Substrate from '@/components/Substrate';
import PlantField from '@/components/PlantField';

const TANK_BOUNDS = new THREE.Vector3(14, 7, 7);

// R3F İçinde Hem Balık Motorunu Güncelleyen Hem De FPS Hesaplayan Bileşen
function SimulationController({
  fishCount,
  fishConfigs,
  onFpsUpdate,
}: {
  fishCount: number;
  fishConfigs: FishConfig[];
  onFpsUpdate: (fps: number) => void;
}) {
  const { scene } = useThree();
  const fishManagerRef = useRef<FishManager | null>(null);

  // FPS Hesabı için ref'ler
  const frameCountRef = useRef(0);
  const lastFpsUpdateRef = useRef(performance.now());

  useEffect(() => {
    if (fishConfigs.length > 0 && !fishManagerRef.current) {
      fishManagerRef.current = new FishManager(scene, TANK_BOUNDS, fishCount, fishConfigs);
    }
  }, [scene, fishConfigs]);

  useEffect(() => {
    if (fishManagerRef.current) {
      fishManagerRef.current.setFishCount(fishCount);
    }
  }, [fishCount]);

  useFrame((state) => {
    const elapsedTime = state.clock.getElapsedTime();

    // 1. Balık Simülasyon Güncellemesi
    if (fishManagerRef.current) {
      fishManagerRef.current.update(elapsedTime);
    }

    // 2. FPS Hesabı (Eski main.js updateFPS mantığı)
    frameCountRef.current++;
    const now = performance.now();
    if (now - lastFpsUpdateRef.current >= 500) {
      const currentFps = Math.round((frameCountRef.current * 1000) / (now - lastFpsUpdateRef.current));
      onFpsUpdate(currentFps);
      frameCountRef.current = 0;
      lastFpsUpdateRef.current = now;
    }
  });

  return null;
}

function GlassBounds() {
  return (
    <lineSegments position={[0, 0, 0]}>
      <edgesGeometry args={[new THREE.BoxGeometry(TANK_BOUNDS.x, TANK_BOUNDS.y, TANK_BOUNDS.z)]} />
      <lineBasicMaterial color="#38bdf8" transparent opacity={0.35} />
    </lineSegments>
  );
}

export default function AquariumScene() {
  const [dbStatus, setDbStatus] = useState<string>('Bağlanıyor...');
  const [fishCount, setFishCount] = useState<number>(20);
  const [fps, setFps] = useState<number>(60);
  const [fishConfigs, setFishConfigs] = useState<FishConfig[]>([]);

  useEffect(() => {
    async function checkConnection() {
      const { error } = await supabase.from('_test_connection').select('*').limit(1);
      if (!error || error.code === 'PGRST116' || error.code === '42P01') {
        setDbStatus('Supabase Bağlantısı Başarılı!');
      } else {
        setDbStatus('Bağlantı Hatası');
      }
    }
    checkConnection();
  }, []);

  useEffect(() => {
    async function loadConfigs() {
      try {
        const res = await fetch('/data/fishConfig.json');
        if (res.ok) {
          const data = await res.json();
          setFishConfigs(data);
        }
      } catch (err) {
        console.error('Konfigürasyon dosyası yüklenemedi:', err);
      }
    }
    loadConfigs();
  }, []);

  return (
    <div className="w-full h-screen relative bg-[#04192b] select-none overflow-hidden">
      {/* Sol Üst: Supabase Bağlantı Rozeti */}
      <div className="absolute top-4 left-4 z-10 bg-[#04192b]/75 text-white px-4 py-2 rounded-xl border border-[#38bdf8]/35 text-sm shadow-2xl backdrop-blur-md">
        Supabase: <span className="text-emerald-400 font-semibold">{dbStatus}</span>
      </div>

      {/* Sağ Üst: UI Kartı (style.css #ui-container ile Birebir Aynı Tasarım) */}
      <div className="absolute top-4 right-4 z-10 bg-[#04192b]/75 text-[#e2f1fd] p-4 rounded-xl border border-[#38bdf8]/35 shadow-2xl backdrop-blur-md flex flex-col gap-3 min-w-[190px]">
        {/* FPS Sayacı */}
        <div className="text-[13px] font-semibold text-[#38bdf8] tracking-wider flex justify-between items-center">
          <span>FPS</span>
          <span className="font-bold text-[#38bdf8]">{fps}</span>
        </div>

        <hr className="border-[#38bdf8]/20" />

        {/* Balık Slider Grubu */}
        <div className="flex flex-col gap-1.5">
          <div className="flex justify-between items-center text-[13px] font-medium">
            <span>Balık Sayısı</span>
            <span className="text-[#38bdf8] font-bold">{fishCount}</span>
          </div>
          <input
            type="range"
            min="1"
            max="100"
            value={fishCount}
            onChange={(e) => setFishCount(parseInt(e.target.value, 10))}
            className="w-full h-[5px] bg-white/20 rounded-lg appearance-none cursor-pointer accent-[#38bdf8]"
          />
        </div>
      </div>

      {/* 3D Canvas Sahnesi */}
      <Canvas
        camera={{ position: [0, 2, 13], fov: 50 }}
        onCreated={({ scene }) => {
          scene.background = new THREE.Color(0x04192b);
          scene.fog = new THREE.FogExp2(0x04192b, 0.045);
        }}
      >
        <directionalLight position={[0, 8, 2]} intensity={2.2} color="#dcf4ff" />
        <ambientLight intensity={1.4} color="#0a3c59" />

        {/* Akvaryum Ortam Elemanları */}
        <GlassBounds />
        <Substrate tankBounds={TANK_BOUNDS} />
        <PlantField tankBounds={TANK_BOUNDS} />

        {/* Simülasyon & FPS Kontrolcüsü */}
        <SimulationController
          fishCount={fishCount}
          fishConfigs={fishConfigs}
          onFpsUpdate={setFps}
        />

        <OrbitControls makeDefault enableDamping dampingFactor={0.05} />
      </Canvas>
    </div>
  );
}